import('puppeteer-core').then(async ({default: puppeteer}) => {
  const http = await import('node:http'); const fs = await import('node:fs'); const path = await import('node:path');
  const ROOT = 'D:/project-5';
  const missing = [];
  const server = http.createServer((req,res)=>{ const p = path.join(ROOT, req.url==='/'?'index.html':decodeURIComponent(req.url.split('?')[0])); try { res.end(fs.readFileSync(p)); } catch { missing.push(req.url); res.statusCode=404; res.end(); } });
  await new Promise(r=>server.listen(0,r));
  const browser = await puppeteer.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe', headless:'new'});
  const page = await browser.newPage();
  await page.goto('http://localhost:'+server.address().port+'/');
  await new Promise(r=>setTimeout(r,4000));
  console.log('404s:', JSON.stringify(missing));
  await browser.close(); server.close(); process.exit(0);
});"
